// The byte fingerprints a module checks before it patches or calls EDF.dll's code (TimeDateStamp 0x678CCB46): one
// table a module (generated by its tools/*_sigs.py into a .inc, audited against the real EDF.dll by its
// tests/*_native_audit.py), one check for all of them. A mismatch (or an unreadable page) is logged as
// "<tag> REFUSED: code at EDF+0x... is not the expected (n bytes)" and the module stays off.
#pragma once
#include "crew.h"
#include <cstddef>

namespace crew {
struct CodeSignature { std::size_t rva; const unsigned char* bytes; std::size_t size; };

inline bool CheckSignatures(const CodeSignature* sigs,std::size_t count,const char* tag) noexcept {
    for(std::size_t i=0;i<count;++i) {
        const CodeSignature& s=sigs[i];
        bool ok=false;
        __try { ok=Matches(s.rva,s.bytes,s.size); } __except(EXCEPTION_EXECUTE_HANDLER) { ok=false; }
        if(!ok){Log("%s REFUSED: code at EDF+0x%zX is not the expected (%zu bytes)",tag,s.rva,s.size);return false;}
    }
    return true;
}
template<std::size_t N> bool CheckSignatures(const CodeSignature (&sigs)[N],const char* tag) noexcept {
    return CheckSignatures(sigs,N,tag);
}
}  // namespace crew
